const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);
const digestHourSchema = z.number().int().min(0).max(23);
const flagOverridesSchema = z.array(z.string());

export const organizationSettingsSchema = z.object({
  defaultIssueStatus: issueStatusSchema.default("backlog"),
  allowPublicProjects: z.boolean().default(false),
  requireTwoFactor: z.boolean().default(false),
  digestHourUtc: digestHourSchema.default(7),
  enabledFlagOverrides: flagOverridesSchema.default([]),
});

/**
 * Update patch. Omitted keys stay omitted: Zod 4 still applies `.default()`
 * through `.partial()`, which would reset every setting the form did not send.
 * `0`, `false`, and `[]` are real values and must survive parsing.
 */
export const organizationSettingsPatchSchema = z.object({
  defaultIssueStatus: issueStatusSchema.optional(),
  allowPublicProjects: z.boolean().optional(),
  requireTwoFactor: z.boolean().optional(),
  digestHourUtc: digestHourSchema.optional(),
  enabledFlagOverrides: flagOverridesSchema.optional(),
});

